    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles with unrolling
    int numTiles = (N + BLOCK_SIZE - 1) / BLOCK_SIZE;
    for (int t = 0; t < numTiles; t += UNROLL_FACTOR) {
        // Preload multiple tiles
        for (int u = 0; u < UNROLL_FACTOR; u++) {
            int tile = t + u;
            if (tile < numTiles) {
                // Load tile from A
                int a_col = tile * BLOCK_SIZE + threadIdx.x;
                if (row < N && a_col < N) {
                    As[threadIdx.y][threadIdx.x] = A[row * N + a_col];
