#include <torch/extension.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 16
#define TILE_SIZE 4

typedef float4 float4_t;

__global__ void matrix_mult_kernel(const float* __restrict__ A, 
                                  const float* __restrict__ B, 
                                  float* __restrict__ C, 
                                  int N) {
    // Shared memory for tiles
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    // Thread coordinates
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x * BLOCK_SIZE;
    int by = blockIdx.y * BLOCK_SIZE;

    // Register accumulation
    float accum[TILE_SIZE][TILE_SIZE] = {{0}};

    // Loop over tiles
    for (int t = 0; t < N; t += BLOCK_SIZE) {
        // Load tile from A using float4 for vectorized access
        if (by + ty < N && t + tx < N) {
            As[ty][tx] = A[(by + ty) * N + t + tx];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile from B using float4 for vectorized access
        if (t + ty < N && bx + tx < N) {
            Bs[ty][tx] = B[(t + ty) * N + bx + tx];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum with register tiling
        for (int k = 0; k < BLOCK_SIZE; k++) {
            float a_val = As[ty][k];
            for (int i = 0; i < TILE_SIZE; i++) {
